import pandas as pd
import json
import os
import shutil

def task_func(path):
    """
    Process JSON files in `path`, combine them into a single DataFrame,
    add a Source column with the filename, and move processed files to
    `path/processed`.

    Parameters
    ----------
    path : str or os.PathLike
        Directory containing JSON files.

    Returns
    -------
    pandas.DataFrame
        DataFrame containing the data from all processed files.
    """
    path = os.fspath(path)
    os.makedirs(path, exist_ok=True)

    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    json_files = sorted(
        filename
        for filename in os.listdir(path)
        if filename.lower().endswith(".json")
        and os.path.isfile(os.path.join(path, filename))
    )

    frames = []

    for filename in json_files:
        file_path = os.path.join(path, filename)

        with open(file_path, "r", encoding="utf-8") as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                f.seek(0)
                data = pd.read_json(f)

        if isinstance(data, dict):
            df = pd.json_normalize(data)
        elif isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                df = pd.json_normalize(data)
            else:
                df = pd.DataFrame(data)
        else:
            df = pd.DataFrame([data])

        if "Source" in df.columns:
            df = df.drop(columns=["Source"])
        df.insert(0, "Source", filename)

        frames.append(df)

        destination = os.path.join(processed_dir, filename)
        if os.path.exists(destination):
            if os.path.isdir(destination):
                shutil.rmtree(destination)
            else:
                os.remove(destination)
        shutil.move(file_path, destination)

    if frames:
        return pd.concat(frames, ignore_index=True, sort=False)

    return pd.DataFrame()
